// Pairwise addition: sums consecutive pairs (a[0]+a[1], a[2]+a[3], ...).
// Assumes `a.len()` is even.
pub fn pairwise_addition(a: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(a.len() / 2);

    for i in (0..a.len()).step_by(2) {
        result.push(a[i] + a[i + 1]);
    }

    result
}

